                "value": record["value"],
            }
            for record in fused
        ]
        data[element] = idw_grid(
            stations,
            lats,
            lons,
            power=power,
            radius_km=radius_km,
            min_points=min_points,
        )

    return {"schema": _SCHEMA, "data": data}
